interface ExactRenderingRecord {
  readonly validationId: string;
  readonly input: string;
  readonly expectedBraille: string;
}

interface MappingCarrierRecord {
  readonly family: GermanKurzschriftMappingFamily;
  readonly carrier: string;
  readonly runtimeKey: string;
  readonly braille: string;
  readonly allowStandalone: boolean;
  readonly sourceSemantics: string | null;
}

interface DecisionSourceRow {
  readonly id: string;
  readonly source: string;
  readonly category: unknown;
  readonly inputField: string | null;
  readonly input: string | null;
  readonly targetField: string | null;
  readonly target: string | null;
  readonly expectedDecision: unknown;
  readonly expectedPolicyClass: unknown;
  readonly ruleRefs: readonly unknown[];
}

interface DecisionPairRecord {
  readonly input: string;
  readonly target: string;
  readonly resolutionKind:
    | "UNIQUE_SOURCE_DECISION"
    | "CONSISTENT_SOURCE_DUPLICATE"
    | "COMPATIBLE_LAYERED_ALLOW"
    | "SOURCE_PRECEDENCE_WITH_HISTORICAL_GUARD";
  readonly operativeDecision: string;
  readonly action:
    | "APPLY_TARGET"
    | "KEEP_PARENT"
    | "POLICY_ONLY";
  readonly rows: readonly DecisionSourceRow[];
}

interface AutomaticData {
  readonly exactRenderingRegistry:
    Readonly<Record<string, ExactRenderingRecord>>;
  readonly mappingCarrierRegistry:
    Readonly<Record<string, readonly MappingCarrierRecord[]>>;
  readonly decisionPairRegistry:
    Readonly<Record<string, DecisionPairRecord>>;
  readonly inputTargetIndex:
    Readonly<Record<string, readonly string[]>>;
  readonly inputOnlyDecisionRegistry:
    Readonly<Record<string, readonly DecisionSourceRow[]>>;
}

