const DATA:
  AutomaticData =
    AUTOMATIC_DATA;

function upperKey(
  value: string,
): string {
  return value
    .normalize("NFC")
    .toLocaleUpperCase("de-DE");
}

function exactKey(
  value: string,
): string {
  return value.normalize("NFC");
}

function pairKey(
  input: string,
  target: string,
): string {
  return (
    upperKey(input)
    + "\u0000"
    + upperKey(target)
  );
}

export interface GermanKurzschriftAutomaticDecisionSuccess {
  readonly ok: true;
  readonly input: string;
  readonly target: string;
  readonly resolutionKind:
    DecisionPairRecord["resolutionKind"];
  readonly operativeDecision: string;
  readonly action:
    DecisionPairRecord["action"];
  readonly sourceRows:
    readonly DecisionSourceRow[];
}

export interface GermanKurzschriftAutomaticDecisionFailure {
  readonly ok: false;
  readonly input: string;
  readonly target: string;
  readonly code:
    "SOURCE_CONTEXT_UNRESOLVED";
  readonly message: string;
}

export type GermanKurzschriftAutomaticDecisionResult =
  | GermanKurzschriftAutomaticDecisionSuccess
  | GermanKurzschriftAutomaticDecisionFailure;

export function resolveGermanKurzschriftAutomaticDecision(
  input: string,
  target: string,
): GermanKurzschriftAutomaticDecisionResult {
  const record =
    DATA.decisionPairRegistry[
      pairKey(
        input,
        target,
      )
    ];

  if (record === undefined) {
    return Object.freeze({
      ok: false,
      input,
      target,
      code:
        "SOURCE_CONTEXT_UNRESOLVED",
      message:
        "No closed source-backed Kurzschrift decision is registered for this input/target pair.",
    });
  }

  return Object.freeze({
    ok: true,
    input,
    target,
    resolutionKind:
      record.resolutionKind,
    operativeDecision:
      record.operativeDecision,
    action:
      record.action,
    sourceRows:
      Object.freeze(
        record.rows.slice(),
      ),
  });
}

export interface GermanKurzschriftAutomaticMappingSuccess {
  readonly ok: true;
  readonly carrier: string;
  readonly unicodeBraille: string;
  readonly families:
    readonly GermanKurzschriftMappingFamily[];
  readonly sourceEntries:
    readonly MappingCarrierRecord[];
}

export interface GermanKurzschriftAutomaticMappingFailure {
  readonly ok: false;
  readonly carrier: string;
  readonly code:
    | "UNKNOWN_MAPPING_CARRIER"
    | "AMBIGUOUS_MAPPING_CARRIER"
    | "MAPPING_EXECUTION_FAILURE";
  readonly message: string;
}

export type GermanKurzschriftAutomaticMappingResult =
  | GermanKurzschriftAutomaticMappingSuccess
  | GermanKurzschriftAutomaticMappingFailure;

export function resolveGermanKurzschriftAutomaticMappingCarrier(
  carrier: string,
  standaloneOnly = false,
): GermanKurzschriftAutomaticMappingResult {
  const sourceEntries =
    DATA.mappingCarrierRegistry[
      upperKey(
        carrier,
      )
    ];

  if (
    sourceEntries === undefined
    || sourceEntries.length === 0
  ) {
    return Object.freeze({
      ok: false,
      carrier,
      code:
        "UNKNOWN_MAPPING_CARRIER",
      message:
        "No closed source-backed Kurzschrift mapping carrier is registered.",
    });
  }

  const entries =
    (
      standaloneOnly
      ? sourceEntries.filter(
          (item) =>
            item.allowStandalone,
        )
      : sourceEntries.slice()
    );

  if (entries.length === 0) {
    return Object.freeze({
      ok: false,
      carrier,
      code:
        "UNKNOWN_MAPPING_CARRIER",
      message:
        "The carrier exists, but not for the requested standalone context.",
    });
  }

  const outputs =
    Array.from(
      new Set(
        entries.map(
          (item) =>
            item.braille,
        ),
      ),
    );

  if (outputs.length !== 1) {
    return Object.freeze({
      ok: false,
      carrier,
      code:
        "AMBIGUOUS_MAPPING_CARRIER",
      message:
        "Multiple source families assign different Braille outputs to this carrier; no precedence was invented.",
    });
  }

  for (const entry of entries) {
    const executed =
      getGermanKurzschriftMapping(
        entry.family,
        entry.runtimeKey,
      );

    if (
      !executed.ok
      || executed.unicodeBraille
        !== entry.braille
    ) {
      return Object.freeze({
        ok: false,
        carrier,
        code:
          "MAPPING_EXECUTION_FAILURE",
        message:
          "Existing source-backed Kurzschrift mapping executor no longer agrees with the automatic carrier registry.",
      });
    }
  }

  return Object.freeze({
    ok: true,
    carrier,
    unicodeBraille:
      outputs[0]!,
    families:
      Object.freeze(
        entries.map(
          (item) =>
            item.family,
        ),
      ),
    sourceEntries:
      Object.freeze(
        entries.slice(),
      ),
  });
}

export interface GermanKurzschriftAutomaticExecutionSuccess {
  readonly ok: true;
  readonly input: string;
  readonly unicodeBraille: string;
  readonly cells: readonly string[];
  readonly path:
    | "EXACT_SOURCE_RENDERING"
    | "STANDALONE_MAPPING"
    | "SOURCE_DECISION_TARGET"
    | "COMPOSED_SEGMENTS"
    | "PARENT_VOLLSCHRIFT";
  readonly sourceValidationId?: string;
  readonly sourceDecision?: {
    readonly target: string;
    readonly operativeDecision: string;
    readonly resolutionKind:
      DecisionPairRecord["resolutionKind"];
  };
  readonly runtime: {
    readonly language: "de";
    readonly mode: "kurzschrift";
    readonly executable: true;
    readonly automaticProviderResolutionExecutable: true;
    readonly provider:
      typeof GERMAN_KURZSCHRIFT_AUTOMATIC_PROVIDER_KIND;
    readonly unknownContextPolicy:
      typeof GERMAN_KURZSCHRIFT_AUTOMATIC_UNKNOWN_CONTEXT_POLICY;
    readonly runtimePrecedenceTotalOrderInvented: false;
    readonly runtimeRegistered: false;
  };
}

export interface GermanKurzschriftAutomaticExecutionFailure {
  readonly ok: false;
  readonly input: string;
  readonly code:
    | "SOURCE_CONTEXT_UNRESOLVED"
    | "SOURCE_RENDERING_FAILURE"
    | "PARENT_VOLLSCHRIFT_FAILURE";
  readonly message: string;
  readonly target?: string;
}

export type GermanKurzschriftAutomaticExecutionResult =
  | GermanKurzschriftAutomaticExecutionSuccess
  | GermanKurzschriftAutomaticExecutionFailure;

function success(
  input: string,
  unicodeBraille: string,
  path:
    GermanKurzschriftAutomaticExecutionSuccess["path"],
  extra: {
    readonly sourceValidationId?: string;
    readonly sourceDecision?: {
      readonly target: string;
      readonly operativeDecision: string;
      readonly resolutionKind:
        DecisionPairRecord["resolutionKind"];
    };
  } = {},
): GermanKurzschriftAutomaticExecutionSuccess {
  return Object.freeze({
    ok: true,
    input,
    unicodeBraille,
    cells:
      Object.freeze(
        Array.from(
          unicodeBraille,
        ),
      ),
    path,
    ...extra,
    runtime:
      Object.freeze({
        language: "de",
        mode: "kurzschrift",
        executable: true,
        automaticProviderResolutionExecutable:
          true,
        provider:
          GERMAN_KURZSCHRIFT_AUTOMATIC_PROVIDER_KIND,
        unknownContextPolicy:
          GERMAN_KURZSCHRIFT_AUTOMATIC_UNKNOWN_CONTEXT_POLICY,
        runtimePrecedenceTotalOrderInvented:
          false,
        runtimeRegistered:
          false,
      }),
  });
}

function parent(
  input: string,
): GermanKurzschriftAutomaticExecutionResult {
  const result =
    translateGermanVollschriftAutomatic(
      input,
    );

  if (!result.ok) {
    return Object.freeze({
      ok: false,
      input,
      code:
        "PARENT_VOLLSCHRIFT_FAILURE",
      message:
        "Automatic Vollschrift parent could not resolve this context without guessing.",
    });
  }

  return success(
    input,
    result.unicodeBraille,
    "PARENT_VOLLSCHRIFT",
  );
}

function uniqueCaseInsensitiveTargetRange(
  input: string,
  target: string,
): {
  readonly start: number;
  readonly end: number;
} | null {
  const source =
    input
      .normalize("NFC")
      .toLocaleLowerCase("de-DE");

  const needle =
    target
      .normalize("NFC")
      .toLocaleLowerCase("de-DE");

  if (
    needle.length === 0
  ) {
    return null;
  }

  const start =
    source.indexOf(
      needle,
    );

  if (
    start < 0
  ) {
    return null;
  }

  if (
    source.indexOf(
      needle,
      start + needle.length,
    )
    >= 0
  ) {
    return null;
  }

  return Object.freeze({
    start,
    end:
      start + needle.length,
  });
}

// POST15_GERMAN_SENTENCE_COMPOSITION_FIX
//
// Kurzschrift's source-backed single-word/phrase resolver remains authoritative.
// For a larger text selection that has no whole-input decision, compose lexical
// segments from that same resolver and preserve structural spans through the
// Vollschrift/Basisschrift parent instead of treating the entire selection as
// one unresolved lexical witness.
function isGermanLexicalCodePoint(
  value: string,
): boolean {
  return /^[\p{L}\p{M}]$/u.test(value);
}

interface GermanKurzschriftCompositionSegment {
  readonly text: string;
  readonly lexical: boolean;
}

function splitGermanKurzschriftCompositionSegments(
  input: string,
): readonly GermanKurzschriftCompositionSegment[] {
  const chars =
    Array.from(
      input.normalize("NFC"),
    );

  if (chars.length === 0) {
    return Object.freeze([]);
  }

  const segments:
    GermanKurzschriftCompositionSegment[] = [];

  let start = 0;

  while (start < chars.length) {
    const lexical =
      isGermanLexicalCodePoint(
        chars[start]!,
      );

    let end =
      start + 1;

    while (
      end < chars.length
      && isGermanLexicalCodePoint(
        chars[end]!,
      ) === lexical
    ) {
      end += 1;
    }

    segments.push(
      Object.freeze({
        text:
          chars
            .slice(start, end)
            .join(""),
        lexical,
      }),
    );

    start = end;
  }

  return Object.freeze(
    segments.slice(),
  );
}

function composeGermanKurzschriftSegments(
  input: string,
): GermanKurzschriftAutomaticExecutionResult | null {
  const segments =
    splitGermanKurzschriftCompositionSegments(
      input,
    );

  const lexicalCount =
    segments.filter(
      (segment) =>
        segment.lexical,
    ).length;

  if (lexicalCount < 2) {
    return null;
  }

  const output: string[] = [];

  for (const segment of segments) {
    if (segment.lexical) {
      const translated =
        translateGermanKurzschriftAutomatic(
          segment.text,
        );

      if (!translated.ok) {
        return Object.freeze({
          ok: false,
          input,
          code:
            translated.code,
          message:
            "Kurzschrift sentence composition could not resolve lexical segment "
            + JSON.stringify(segment.text)
            + ": "
            + translated.message,
          ...(translated.target === undefined
            ? {}
            : {
                target:
                  translated.target,
              }),
        });
      }

      output.push(
        translated.unicodeBraille,
      );
      continue;
    }

    const structural =
      translateGermanVollschriftAutomatic(
        segment.text,
      );

    if (!structural.ok) {
      return Object.freeze({
        ok: false,
        input,
        code:
          "PARENT_VOLLSCHRIFT_FAILURE",
        message:
          "Kurzschrift sentence composition could not preserve a structural separator through the Vollschrift parent.",
      });
    }

    output.push(
      structural.unicodeBraille,
    );
  }

  return success(
    input,
    output.join(""),
    "COMPOSED_SEGMENTS",
  );
}

export function translateGermanKurzschriftAutomatic(
  input: string,
): GermanKurzschriftAutomaticExecutionResult {
  const exact =
    DATA.exactRenderingRegistry[
      exactKey(
        input,
      )
    ];

  if (exact !== undefined) {
    const rendered =
      getGermanKurzschriftSourceRendering(
        exact.validationId,
        exact.input,
      );

    if (
      !rendered.ok
      || rendered.unicodeBraille
        !== exact.expectedBraille
    ) {
      return Object.freeze({
        ok: false,
        input,
        code:
          "SOURCE_RENDERING_FAILURE",
        message:
          "Closed source rendering registry no longer agrees with the existing Kurzschrift executor.",
      });
    }

    return success(
      input,
      rendered.unicodeBraille,
      "EXACT_SOURCE_RENDERING",
      {
        sourceValidationId:
          exact.validationId,
      },
    );
  }

  const standalone =
    resolveGermanKurzschriftAutomaticMappingCarrier(
      input,
      true,
    );

  if (standalone.ok) {
    return success(
      input,
      standalone.unicodeBraille,
      "STANDALONE_MAPPING",
    );
  }

  const inputKey =
    upperKey(
      input,
    );

  const targets =
    DATA.inputTargetIndex[
      inputKey
    ];

  if (
    targets !== undefined
    && targets.length > 0
  ) {
    if (
      targets.length !== 1
    ) {
      // POST15_GERMAN_ONE_HOUR_CLOSURE_ACCELERATOR
      return parent(
        input,
      );
    }

    const target =
      targets[0]!;

    const decision =
      resolveGermanKurzschriftAutomaticDecision(
        input,
        target,
      );

    if (!decision.ok) {
      return parent(
        input,
      );
    }

    if (
      decision.action
      === "KEEP_PARENT"
    ) {
      return parent(
        input,
      );
    }

    if (
      decision.action
      !== "APPLY_TARGET"
    ) {
      return parent(
        input,
      );
    }

    const mapping =
      resolveGermanKurzschriftAutomaticMappingCarrier(
        target,
        false,
      );

    if (!mapping.ok) {
      if (
        mapping.code
        === "MAPPING_EXECUTION_FAILURE"
      ) {
        return Object.freeze({
          ok: false,
          input,
          target,
          code:
            "SOURCE_RENDERING_FAILURE",
          message:
            mapping.message,
        });
      }

      return parent(
        input,
      );
    }

    const range =
      uniqueCaseInsensitiveTargetRange(
        input,
        target,
      );

    if (range === null) {
      return parent(
        input,
      );
    }

    const prefixText =
      input.slice(
        0,
        range.start,
      );

    const suffixText =
      input.slice(
        range.end,
      );

    const prefix =
      prefixText.length === 0
      ? null
      : translateGermanVollschriftAutomatic(
          prefixText,
        );

    const suffix =
      suffixText.length === 0
      ? null
      : translateGermanVollschriftAutomatic(
          suffixText,
        );

    if (
      (
        prefix !== null
        && !prefix.ok
      )
      || (
        suffix !== null
        && !suffix.ok
      )
    ) {
      return parent(
        input,
      );
    }

    const unicodeBraille =
      (
        prefix === null
        ? ""
        : prefix.unicodeBraille
      )
      + mapping.unicodeBraille
      + (
        suffix === null
        ? ""
        : suffix.unicodeBraille
      );

    return success(
      input,
      unicodeBraille,
      "SOURCE_DECISION_TARGET",
      {
        sourceDecision:
          Object.freeze({
            target,
            operativeDecision:
              decision.operativeDecision,
            resolutionKind:
              decision.resolutionKind,
          }),
      },
    );
  }

  const inputOnly =
    DATA.inputOnlyDecisionRegistry[
      inputKey
    ];

  if (
    inputOnly !== undefined
    && inputOnly.length > 0
  ) {
    return parent(
      input,
    );
  }

  const composed =
    composeGermanKurzschriftSegments(
      input,
    );

  if (composed !== null) {
    return composed;
  }

  return parent(
    input,
  );
}
